# In session_manager.rs, inside create_session:
pub async fn create_session(&self, /* ...same params... */) -> Arc<SessionRuntime> {
    let session_id = SessionId::new();
    let runtime = Arc::new(SessionRuntime::new_with_toolset(/* ... */));
    self.sessions.write().await.insert(session_id, runtime.clone());

    if let Some(handle) = runtime.take_root_task_handle() {
        let runtime_for_supervisor = runtime.clone();
        tokio::spawn(async move {
            if let Err(join_err) = handle.await {
                tracing::error!(%session_id, error = %join_err, "session root task panicked");
                runtime_for_supervisor.mark_failed(join_err.to_string());
            }
        });
    }
    runtime
}

pub async fn subscribe(
    &self,
    id: SessionId,
) -> Result<broadcast::Receiver<AgentEventEnvelope>, SessionManagerError> {
    self.session_handle(id)
        .await
        .map(|runtime| runtime.event_bus.subscribe())
        .ok_or(SessionManagerError::NotFound(id))
}

pub struct SchedulerConfig {
    pub max_active_sessions: usize,
    pub max_active_agents: usize,
    pub max_agents_per_session: usize,
    pub max_concurrent_backend_requests: usize,
    pub max_concurrent_tool_executions: usize,
    pub max_concurrent_processes: usize,
}

impl Default for SchedulerConfig {
    fn default() -> Self {
        Self {
            max_active_sessions: 64,
            max_active_agents: 256,
            max_agents_per_session: 32,
            max_concurrent_backend_requests: 8,
            max_concurrent_tool_executions: 16,
            max_concurrent_processes: 8,
        }
    }
}

pub struct Scheduler {
    sessions: Arc<Semaphore>,
    agents: Arc<Semaphore>,
    backend_requests: Arc<Semaphore>,
    tool_executions: Arc<Semaphore>,
    processes: Arc<Semaphore>,
}

impl Scheduler {
    pub fn new(config: SchedulerConfig) -> Self {
        Self {
            sessions: Arc::new(Semaphore::new(config.max_active_sessions)),
            agents: Arc::new(Semaphore::new(config.max_active_agents)),
            backend_requests: Arc::new(Semaphore::new(config.max_concurrent_backend_requests)),
            tool_executions: Arc::new(Semaphore::new(config.max_concurrent_tool_executions)),
            processes: Arc::new(Semaphore::new(config.max_concurrent_processes)),
        }
    }

    pub async fn acquire_session_permit(self: &Arc<Self>) -> OwnedSemaphorePermit {
        self.sessions.clone().acquire_owned().await.expect("semaphore not closed")
    }

    pub async fn acquire_backend_permit(self: &Arc<Self>) -> OwnedSemaphorePermit {
        self.backend_requests.clone().acquire_owned().await.expect("semaphore not closed")
    }

    pub async fn acquire_tool_permit(self: &Arc<Self>) -> OwnedSemaphorePermit {
        self.tool_executions.clone().acquire_owned().await.expect("semaphore not closed")
    }
}

