    use super::*;

    // -----------------------------------------------------------------------
    // Helper: drain buffered events from a broadcast receiver non-blockingly
    // -----------------------------------------------------------------------

    fn drain_events(rx: &mut broadcast::Receiver<AgentEventEnvelope>) -> Vec<AgentEvent> {
        let mut events = Vec::new();
        while let Ok(envelope) = rx.try_recv() {
            events.push(envelope.event);
        }
        events
    }

    // -----------------------------------------------------------------------
    // Test: session event bus produces a well-ordered event stream
    // -----------------------------------------------------------------------

    /// Verifies that subscribing to the session event bus and sending
    /// `SessionCommand::Prompt` produces a well-ordered stream.
    ///
    /// The Phase 1 state machine emits these events for a
    /// TextDelta → Completed sequence:
    ///   StateChanged(Idle → PreparingContext)
    ///   RunStarted
    ///   StateChanged(PreparingContext → Streaming)
    ///   AssistantTextDelta("Hello, world!")
    ///   StateChanged(Streaming → Idle)
    ///   Completed { Success }
    #[tokio::test]
    async fn session_prompt_produces_ordered_event_stream() {
        // ── Setup ────────────────────────────────────────
        let session_id = SessionId::new();
        let request_id = RequestId::new();

        let backend = Arc::new(
            FakeBackend::new()
                .with_events(vec![
                    ExecutionEvent::TextDelta {
                        request_id,
                        delta: "Hello, world!".into(),
                    },
                    ExecutionEvent::Completed {
                        request_id,
                        result: ExecutionResult {
                            request_id,
                            usage: ModelUsage::default(),
                            cost: Cost::default(),
                            finish_reason: "end_turn".into(),
                        },
                    },
                ])
                .with_result(ExecutionResult {
                    request_id,
                    usage: ModelUsage::default(),
                    cost: Cost::default(),
                    finish_reason: "end_turn".into(),
                }),
        );

        let tool_registry = Arc::new(FakeToolRegistry::new());
        let workspace = Arc::new(FakeWorkspace::new());

        // Use a no-op event sink for the external persistence/logging path.
        struct NoopSink;
        impl EventSink for NoopSink {
            fn send(&self, _envelope: AgentEventEnvelope) {}
        }

        let runtime = SessionRuntime::new(
            session_id,
            backend,
            tool_registry,
            workspace,
            Arc::new(NoopSink),
        );

        // Subscribe to the event bus before sending any command.
        let mut subscriber = runtime.event_bus.subscribe();

        // ── Act: send Prompt command ────────────────────────
        runtime
            .send_command(SessionCommand::Prompt(UserInput {
                text: "hello".to_string(),
                attachments: vec![],
            }))
            .await
            .expect("send_command should succeed");

        // ── Collect events ─────────────────────────────
        let mut all_events: Vec<AgentEvent> = Vec::new();
        for _ in 0..30 {
            let batch = drain_events(&mut subscriber);
            if !batch.is_empty() {
                all_events.extend(batch);
                if all_events
                    .iter()
                    .any(|e| matches!(e, AgentEvent::Completed { .. }))
                {
                    break;
                }
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }

        // ── Assert ──────────────────────────────────
        // Filter out StateChanged events to see the core sequence.
        let core_events: Vec<&AgentEvent> = all_events
            .iter()
            .filter(|e| !matches!(e, AgentEvent::StateChanged { .. }))
            .collect();

        // Expected core events after StateChanged filtering:
        //   0. RunStarted
        //   1. AssistantTextDelta("Hello, world!")
        //   2. Completed { outcome: Success }
        assert!(
            core_events.len() >= 3,
            "expected at least 3 non-StateChanged events (RunStarted, AssistantTextDelta, Completed); got {}: {:?}",
            core_events.len(),
            core_events,
        );

        assert!(
            matches!(core_events[0], AgentEvent::RunStarted { .. }),
            "event[0] should be RunStarted, got {:?}",
            core_events[0]
        );

        assert!(
            matches!(&core_events[1], AgentEvent::AssistantTextDelta { delta, .. } if delta == "Hello, world!"),
            "event[1] should be AssistantTextDelta(\"Hello, world!\"), got {:?}",
            core_events[1]
        );

        assert!(
            matches!(core_events[2], AgentEvent::Completed { outcome } if *outcome == AgentOutcome::Success),
            "event[2] should be Completed(Success), got {:?}",
            core_events[2]
        );

        // Verify ordering.
        let run_started_idx = all_events
            .iter()
            .position(|e| matches!(e, AgentEvent::RunStarted { .. }));
        let delta_idx = all_events
            .iter()
            .position(|e| matches!(e, AgentEvent::AssistantTextDelta { .. }));
        let completed_idx = all_events
            .iter()
            .position(|e| matches!(e, AgentEvent::Completed { .. }));

        assert!(
            run_started_idx < delta_idx,
            "RunStarted should precede AssistantTextDelta"
        );
        assert!(
            delta_idx < completed_idx,
            "AssistantTextDelta should precede Completed"
        );
    }

    // -----------------------------------------------------------------------
    // Test: agent_live_state reflects live status transitions and usage
    // -----------------------------------------------------------------------

    /// Verifies that [`SessionRuntime::agent_live_state`] is a truthful,
    /// continuously-updated projection: it starts `Idle`, transitions away
    /// from `Idle` while the run is in flight, and ends with a recorded
    /// `Success` outcome and non-empty usage once the run completes.
    #[tokio::test]
    async fn agent_live_state_reflects_run_lifecycle() {
        let session_id = SessionId::new();
        let request_id = RequestId::new();

        let backend = Arc::new(
            FakeBackend::new()
                .with_events(vec![ExecutionEvent::TextDelta {
                    request_id,
                    delta: "hi".into(),
                }])
                .with_result(ExecutionResult {
                    request_id,
                    usage: ModelUsage {
                        input_tokens: harness_protocol::usage::UsageValue::new(Some(5)),
                        output_tokens: harness_protocol::usage::UsageValue::new(Some(7)),
                        ..Default::default()
                    },
                    cost: Cost::default(),
                    finish_reason: "end_turn".into(),
                }),
        );
        let tool_registry = Arc::new(FakeToolRegistry::new());
        let workspace = Arc::new(FakeWorkspace::new());

        struct NoopSink;
        impl EventSink for NoopSink {
            fn send(&self, _envelope: AgentEventEnvelope) {}
        }

        let runtime = SessionRuntime::new(
            session_id,
            backend,
            tool_registry,
            workspace,
            Arc::new(NoopSink),
        );

        let root_id = runtime.state.root_agent_id;

        // Before any command, live state is the default (Idle, no outcome).
        let before = runtime.agent_live_state(root_id);
        assert_eq!(before.status, AgentStatus::Idle);
        assert!(before.last_outcome.is_none());

        let mut subscriber = runtime.event_bus.subscribe();

        runtime
            .send_command(SessionCommand::Prompt(UserInput {
                text: "hello".to_string(),
                attachments: vec![],
            }))
            .await
            .expect("send_command should succeed");

        // Poll until a Completed event has been observed.
        let mut completed = false;
        for _ in 0..50 {
            let batch = drain_events(&mut subscriber);
            if batch.iter().any(|e| matches!(e, AgentEvent::Completed { .. })) {
                completed = true;
                break;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        assert!(completed, "run should complete within the polling window");

        // Give the runner one more tick to publish the post-completion status.
        tokio::time::sleep(Duration::from_millis(20)).await;

        let after = runtime.agent_live_state(root_id);
        assert_eq!(
            after.last_outcome,
            Some(AgentOutcome::Success),
            "last_outcome should be Success after the run completes"
        );
        assert_eq!(
            after.usage.inclusive_usage.input_tokens.value(),
            Some(5),
            "usage should be populated from the scripted ExecutionResult"
        );
        assert_eq!(after.total_requests, 1);
    }
}

//! Session lifecycle management for the harness runtime.
//!
//! [`SessionManager`] owns the set of all active agent sessions and provides
//! thread-safe (async) access to create, close, query, and (in future) restore
//! sessions. Each session is identified by a globally unique [`SessionId`] and
//! backed by an `Arc<SessionRuntime>`.
//!
//! # Concurrency
//!
//! Internal state is guarded by a `tokio::sync::RwLock` over a
//! `HashMap<SessionId, Arc<SessionRuntime>>`, matching the crate's existing
//! async‑first idiom. Lock contention is minimal because the common path
//! (`session_handle` / `active_session_ids`) only acquires a read lock.

use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

use harness_protocol::ids::SessionId;
use harness_protocol::tools::AgentToolset;

use crate::session_runtime::SessionRuntime;
use crate::traits::{EventSink, ExecutionBackend, ToolRegistry, Workspace};

/// Errors that can occur during session management operations.
#[derive(Debug, thiserror::Error)]
pub enum SessionManagerError {
    /// The requested [`SessionId`] does not correspond to any active session.
    #[error("session {0} not found")]
    NotFound(SessionId),

    /// [`SessionManager::restore_session`] was called, but session persistence
    /// is not yet supported. This is reserved for a future phase (Phase 7).
    #[error("session restore is not yet supported (Phase 7)")]
    RestoreNotSupported,
}

/// Thread-safe manager for all active agent sessions.
///
/// `SessionManager` is the single entry point for multi-session orchestration.
/// It is cheaply cloneable because the owned map is behind an `Arc` (via the
/// inner `RwLock`). Typical usage:
///
/// ```ignore
/// let manager = SessionManager::new();
///
/// // Spawn a new session
/// let sess = manager.create_session(backend, registry, workspace, sink, toolset).await;
///
/// // Obtain a handle later
/// if let Some(runtime) = manager.session_handle(sess_id).await {
///     runtime.execute(...).await?;
/// }
///
/// // Tear down
/// manager.close_session(sess_id).await?;
/// ```
pub struct SessionManager {
    /// Map from session identifier to the corresponding runtime handle.
    sessions: RwLock<HashMap<SessionId, Arc<SessionRuntime>>>,
}

impl SessionManager {
    /// Creates a new, empty `SessionManager`.
    ///
    /// No sessions are active after construction.
    pub fn new() -> Self {
        Self {
            sessions: RwLock::new(HashMap::new()),
        }
    }

    /// Creates a new agent session and stores its runtime.
    ///
    /// This method:
    /// 1. Generates a fresh, unique [`SessionId`].
    /// 2. Constructs a [`SessionRuntime`] via [`SessionRuntime::new_with_toolset`],
    ///    wiring in the provided [`ExecutionBackend`], [`ToolRegistry`],
    ///    [`Workspace`], [`EventSink`], and [`AgentToolset`].
    /// 3. Inserts the runtime into the internal map under the new ID.
    /// 4. Spawns a supervisor task that observes the root task's completion.
    ///    If the root task panics, the session is marked as `Failed` and the
    ///    error is logged. This ensures that panics in one session do not
    ///    crash the process or affect other sessions.
    ///
    /// Returns an `Arc`-clone of the created runtime so the caller can
    /// immediately start driving the session without an extra lookup.
    pub async fn create_session(
        &self,
        backend: Arc<dyn ExecutionBackend>,
        tool_registry: Arc<dyn ToolRegistry>,
        workspace: Arc<dyn Workspace>,
        event_sink: Arc<dyn EventSink>,
        root_toolset: AgentToolset,
    ) -> Arc<SessionRuntime> {
        let session_id = SessionId::new();
        let runtime = Arc::new(SessionRuntime::new_with_toolset(
            session_id,
            backend,
            tool_registry,
            workspace,
            event_sink,
            root_toolset,
        ));
        self.sessions.write().await.insert(session_id, runtime.clone());

        // Spawn a supervisor task that awaits the root task handle and, on
        // JoinError, marks the session as Failed. This isolates panics so
        // that one session's root task cannot crash the process.
        if let Some(handle) = runtime.take_root_task_handle() {
            let runtime_for_supervisor = runtime.clone();
            tokio::spawn(async move {
                if let Err(join_err) = handle.await {
                    tracing::error!(%session_id, error = %join_err, "session root task panicked");
                    runtime_for_supervisor.mark_failed(join_err.to_string());
                }
            });
        }

        runtime
    }

    /// Returns a handle to the session identified by `id`, or `None` if no such
    /// session exists.
    ///
    /// The returned `Arc<SessionRuntime>` can be used to submit tasks, observe
    /// events, or cancel execution. Because this method only acquires a *read*
    /// lock, it does not block other readers.
    pub async fn session_handle(&self, id: SessionId) -> Option<Arc<SessionRuntime>> {
        self.sessions.read().await.get(&id).cloned()
    }

    /// Closes the session identified by `id`.
    ///
    /// The session is removed from the manager's internal map and its
    /// cancellation token is signalled so that any in-flight work can
    /// be torn down gracefully.
    ///
    /// # Errors
    ///
    /// Returns [`SessionManagerError::NotFound`] when `id` does not match
    /// an active session.
    pub async fn close_session(&self, id: SessionId) -> Result<(), SessionManagerError> {
        let removed = self.sessions.write().await.remove(&id);
        match removed {
            Some(runtime) => {
                runtime.cancellation.cancel();
                Ok(())
            }
            None => Err(SessionManagerError::NotFound(id)),
        }
    }

    /// Restores a previously persisted session (stub).
    ///
    /// Session persistence and restoration will be implemented in a later
    /// phase (Phase 7). Until then, calling this method always returns
    /// [`SessionManagerError::RestoreNotSupported`].
    pub async fn restore_session(
        &self,
        _id: SessionId,
    ) -> Result<Arc<SessionRuntime>, SessionManagerError> {
        Err(SessionManagerError::RestoreNotSupported)
    }

    /// Returns a list of all currently active session IDs.
    ///
    /// The order of the returned [`Vec`] is **not** specified and may vary
    /// between calls. The snapshot is taken under a single read lock, so it
    /// represents a consistent point-in-time view.
    pub async fn active_session_ids(&self) -> Vec<SessionId> {
        self.sessions.read().await.keys().copied().collect()
    }
}

impl Default for SessionManager {
    /// Creates a new, empty `SessionManager`.
    fn default() -> Self {
        Self::new()
    }
}

