//! Session lifecycle management for the harness runtime.
//!
//! [`SessionManager`] owns the set of all active agent sessions and provides
//! thread-safe (async) access to create, close, query, and (in future) restore
//! sessions. Each session is identified by a globally unique [`SessionId`] and
//! backed by an `Arc<SessionRuntime>`.
//!
//! # Concurrency
//!
//! Internal state is guarded by a `tokio::sync::RwLock` over a
//! `HashMap<SessionId, Arc<SessionRuntime>>`, matching the crate's existing
//! async‑first idiom. Lock contention is minimal because the common path
//! (`session_handle` / `active_session_ids`) only acquires a read lock.
//!
//! Session creation is additionally throttled by an injected [`Scheduler`]
//! that limits the number of concurrently active sessions via a semaphore
//! permit acquired inside [`create_session`](SessionManager::create_session).

use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

use harness_protocol::ids::SessionId;
use harness_protocol::tools::AgentToolset;

use crate::scheduler::Scheduler;
use crate::session_runtime::SessionRuntime;
use crate::traits::{EventSink, ExecutionBackend, ToolRegistry, Workspace};

/// Errors that can occur during session management operations.
#[derive(Debug, thiserror::Error)]
pub enum SessionManagerError {
    /// The requested [`SessionId`] does not correspond to any active session.
    #[error("session {0} not found")]
    NotFound(SessionId),

    /// [`SessionManager::restore_session`] was called, but session persistence
    /// is not yet supported. This is reserved for a future phase (Phase 7).
    #[error("session restore is not yet supported (Phase 7)")]
    RestoreNotSupported,
}

/// Thread-safe manager for all active agent sessions.
///
/// `SessionManager` is the single entry point for multi-session orchestration.
/// It is cheaply cloneable because the owned map is behind an `Arc` (via the
/// inner `RwLock`). Typical usage:
///
/// ```ignore
/// let scheduler = Arc::new(Scheduler::new(SchedulerConfig::default()));
/// let manager = SessionManager::new(scheduler);
///
/// // Spawn a new session
/// let sess = manager.create_session(backend, registry, workspace, sink, toolset).await;
///
/// // Obtain a handle later
/// if let Some(runtime) = manager.session_handle(sess_id).await {
///     runtime.execute(...).await?;
/// }
///
/// // Tear down
/// manager.close_session(sess_id).await?;
/// ```
pub struct SessionManager {
    /// Map from session identifier to the corresponding runtime handle.
    sessions: RwLock<HashMap<SessionId, Arc<SessionRuntime>>>,
    /// Concurrency throttle for sessions, agents, backend requests, etc.
    scheduler: Arc<Scheduler>,
}

impl SessionManager {
    /// Creates a new, empty `SessionManager` with the given scheduler.
    ///
    /// No sessions are active after construction.
    pub fn new(scheduler: Arc<Scheduler>) -> Self {
        Self {
            sessions: RwLock::new(HashMap::new()),
            scheduler,
        }
    }

    /// Creates a new agent session and stores its runtime.
    ///
    /// This method:
    /// 1. Acquires a session permit from the [`Scheduler`] (may block if at
    ///    capacity).
    /// 2. Generates a fresh, unique [`SessionId`].
    /// 3. Constructs a [`SessionRuntime`] via [`SessionRuntime::new_with_toolset`],
    ///    wiring in the provided [`ExecutionBackend`], [`ToolRegistry`],
    ///    [`Workspace`], [`EventSink`], [`AgentToolset`], and the scheduler.
    /// 4. Inserts the runtime into the internal map under the new ID.
    ///
    /// Returns an `Arc`-clone of the created runtime so the caller can
    /// immediately start driving the session without an extra lookup.
    ///
    /// # Panics
    ///
    /// Panics if the scheduler's session semaphore has been closed (should
    /// never happen under normal operation).
    pub async fn create_session(
        &self,
        backend: Arc<dyn ExecutionBackend>,
        tool_registry: Arc<dyn ToolRegistry>,
        workspace: Arc<dyn Workspace>,
        event_sink: Arc<dyn EventSink>,
        root_toolset: AgentToolset,
    ) -> Arc<SessionRuntime> {
        // Throttle session creation — block if we've hit the cap.
        let _session_permit = self.scheduler.acquire_session_permit().await;

        let session_id = SessionId::new();
        let runtime = Arc::new(SessionRuntime::new_with_toolset(
            session_id,
            backend,
            tool_registry,
            workspace,
            event_sink,
            root_toolset,
            self.scheduler.clone(),
        ));
        self.sessions.write().await.insert(session_id, runtime.clone());
        runtime
    }

    /// Returns a handle to the session identified by `id`, or `None` if no such
    /// session exists.
    ///
    /// The returned `Arc<SessionRuntime>` can be used to submit tasks, observe
    /// events, or cancel execution. Because this method only acquires a *read*
    /// lock, it does not block other readers.
    pub async fn session_handle(&self, id: SessionId) -> Option<Arc<SessionRuntime>> {
        self.sessions.read().await.get(&id).cloned()
    }

    /// Closes the session identified by `id`.
    ///
    /// The session is removed from the manager's internal map and its
    /// cancellation token is signalled so that any in-flight work can
    /// be torn down gracefully.
    ///
    /// # Errors
    ///
    /// Returns [`SessionManagerError::NotFound`] when `id` does not match
    /// an active session.
    pub async fn close_session(&self, id: SessionId) -> Result<(), SessionManagerError> {
        let removed = self.sessions.write().await.remove(&id);
        match removed {
            Some(runtime) => {
                runtime.cancellation.cancel();
                Ok(())
            }
            None => Err(SessionManagerError::NotFound(id)),
        }
    }

    /// Restores a previously persisted session (stub).
    ///
    /// Session persistence and restoration will be implemented in a later
    /// phase (Phase 7). Until then, calling this method always returns
    /// [`SessionManagerError::RestoreNotSupported`].
    pub async fn restore_session(
        &self,
        _id: SessionId,
    ) -> Result<Arc<SessionRuntime>, SessionManagerError> {
        Err(SessionManagerError::RestoreNotSupported)
    }

    /// Returns a list of all currently active session IDs.
    ///
    /// The order of the returned [`Vec`] is **not** specified and may vary
    /// between calls. The snapshot is taken under a single read lock, so it
    /// represents a consistent point-in-time view.
    pub async fn active_session_ids(&self) -> Vec<SessionId> {
        self.sessions.read().await.keys().copied().collect()
    }
}

impl Default for SessionManager {
    /// Creates a new `SessionManager` with a default [`Scheduler`].
    fn default() -> Self {
        Self::new(Arc::new(Scheduler::new(Default::default())))
    }
}

//! Session runtime — event bus, session state, and lifecycle.
//!
//! This module provides [`SessionEventBus`] — the per-session event aggregator
//! that merges event streams from all agent runners into a single ordered stream
//! for subscribers — and [`SessionRuntime`], the top-level orchestrator that
//! owns a session's root agent, cancellation scope, backend bindings, workspace
//! binding, and event bus.

use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};

use tokio::sync::{broadcast, mpsc};
use tokio_util::sync::CancellationToken;

use harness_core::agent::Agent;
use harness_core::capabilities::{AgentCapabilities, WorkspaceCapabilities};
use harness_core::usage::AgentUsageSummary as CoreAgentUsageSummary;
use harness_protocol::backend::{
    BackendBinding, BackendCapabilities, BackendDescriptor, BackendReference,
};
use harness_protocol::commands::{AgentCommand, AgentError, AgentOperation, AgentStatus, UserInput};
