// Public types
// ---------------------------------------------------------------------------

struct BroadcastEventSink {
    tx: broadcast::Sender<AgentEventEnvelope>,
}

/// Ensures tools configured on the public session builder are advertised to
/// the backend even when the lower-level agent capability projection is empty.
struct ToolAdvertisingBackend {
    inner: Arc<dyn ExecutionBackend>,
    tools: Vec<harness_protocol::tools::ToolDescriptor>,
}

#[async_trait]
impl ExecutionBackend for ToolAdvertisingBackend {
    fn descriptor(&self) -> harness_protocol::backend::BackendDescriptor {
        self.inner.descriptor()
    }

    fn capabilities(&self) -> harness_protocol::backend::BackendCapabilities {
        self.inner.capabilities()
    }

    async fn execute(
        &self,
        mut request: ExecutionRequest,
        sink: broadcast::Sender<ExecutionEvent>,
        cancel: CancellationToken,
    ) -> Result<ExecutionResult, ExecutionError> {
        if request.tools.is_empty() {
            request.tools = self.tools.clone();
        }
        self.inner.execute(request, sink, cancel).await
    }
}

impl EventSink for BroadcastEventSink {
    fn send(&self, envelope: AgentEventEnvelope) {
        let _ = self.tx.send(envelope);
    }
}

/// Errors raised while configuring or operating a session.
#[derive(Debug, thiserror::Error)]
pub enum HarnessError {
    #[error("missing required field: backend")]
    MissingBackend,
    #[error("missing required field: tool_registry")]
    MissingToolRegistry,
    #[error("invalid integration configuration: {0}")]
    InvalidIntegrationConfig(#[from] serde_json::Error),
    #[error("integration error: {0}")]
    Integration(#[from] IntegrationError),
    #[error("session error: {0}")]
    Session(#[from] SessionError),
}

struct PendingIntegration {
    id: String,
    config: serde_json::Value,
}

/// Fluent builder for direct or registry-backed sessions.
pub struct SessionBuilder {
    backend: Option<Arc<dyn ExecutionBackend>>,
    integration: Option<PendingIntegration>,
    integrations: Arc<IntegrationRegistry>,
    tool_registry: Option<Arc<dyn ToolRegistry>>,
    workspace: Option<Arc<dyn harness_runtime::traits::Workspace>>,
    /// The toolset to inject into the root agent's capabilities.
    /// When set alongside `tool_registry`, the builder creates the registry
    /// from the toolset's enabled descriptors via `build_executor_for()`.
    root_toolset: Option<AgentToolset>,
}

impl SessionBuilder {
    /// Create a builder with an empty integration registry.
    pub fn new() -> Self {
        Self::with_integrations(Arc::new(IntegrationRegistry::new()))
    }

    /// Create a builder attached to a shared registry.
    pub fn with_integrations(integrations: Arc<IntegrationRegistry>) -> Self {
        Self {
            backend: None,
            integration: None,
            integrations,
            tool_registry: None,
            workspace: None,
            root_toolset: None,
        }
    }

    /// Inject an already constructed backend.
    pub fn backend(mut self, backend: Arc<dyn ExecutionBackend>) -> Self {
        self.backend = Some(backend);
        self.integration = None;
        self
    }

    /// Select a registered integration and provider-specific configuration.
    ///
    /// Resolution is deferred until [`start`](Self::start), keeping the fluent
    /// builder synchronous while allowing factories to perform async setup.
    pub fn integration<C: Serialize>(
        mut self,
        id: impl Into<String>,
        config: C,
    ) -> Result<Self, HarnessError> {
        self.integration = Some(PendingIntegration {
            id: id.into(),
            config: serde_json::to_value(config)?,
        });
        self.backend = None;
        Ok(self)
    }

    /// Set the session tool registry.
    pub fn tools(mut self, tool_registry: Arc<dyn ToolRegistry>) -> Self {
        self.tool_registry = Some(tool_registry);
        self
    }

    /// Set the workspace, defaulting to an empty in-memory workspace.
    pub fn workspace(mut self, workspace: Arc<dyn harness_runtime::traits::Workspace>) -> Self {
        self.workspace = Some(workspace);
        self
    }

    /// Register an `AgentToolset` into the session.
    ///
    /// This is an alternative to [`tools`](Self::tools) that takes a
    /// high-level tool policy set and a [`Workspace`] reference, creates
    /// the appropriate [`ToolExecutor`] instances via
    /// [`build_executor_for`](Self::build_executor_for), registers them
    /// into a [`SimpleToolRegistry`], and wires both the registry and the
    /// toolset into the root agent's capabilities.
    ///
    /// When this method is used, the builder will automatically populate
    /// the tool registry — there is no need to also call [`tools`](Self::tools).
    ///
    /// The `workspace` argument provides the [`Workspace`] that filesystem
    /// tools (`fs.read`, `fs.edit`, `workspace.search`) will delegate to.
    /// Shell tools (`shell.exec`) ignore the workspace.
    pub fn toolset(
        mut self,
        toolset: AgentToolset,
        workspace: Arc<dyn harness_runtime::traits::Workspace>,
    ) -> Self {
        // 1. Register all tool executors into the registry.
        let registry = harness_runtime::traits::SimpleToolRegistry::new();
        for descriptor in toolset.enabled_descriptors() {
            let executor = self.build_executor_for(descriptor, workspace.clone());
            let _ = registry.register(executor);
        }

        // 2. Wire the registry + toolset into the root Agent's capabilities.
        self.tool_registry = Some(Arc::new(registry));
        self.root_toolset = Some(toolset);
        self.workspace = Some(workspace);
        self
    }

    /// Build the appropriate executor for a given tool descriptor.
    ///
    /// Maps known descriptor name strings to concrete tool implementations.
    fn build_executor_for(
        &self,
        descriptor: &harness_protocol::tools::ToolDescriptor,
        workspace: Arc<dyn harness_runtime::traits::Workspace>,
    ) -> Arc<dyn harness_runtime::traits::ToolExecutor> {
        match descriptor.name.as_str() {
            "fs.read" => Arc::new(ReadTool::new(workspace)),
            "fs.edit" => Arc::new(EditTool::new(workspace)),
            "workspace.search" => Arc::new(SearchTool::new(workspace)),
            "shell.exec" => Arc::new(ExecTool::new()),
            _ => {
                // Create a fallback that always fails
                // Convert protocol descriptor to harness-tools descriptor
                let tool_desc = harness_tools::ToolDescriptor {
                    id: harness_tools::ToolId::new(&descriptor.name),
                    name: descriptor.name.clone(),
                    description: descriptor.description.clone(),
                    input_schema: descriptor.input_schema.clone(),
                };
                Arc::new(harness_tools::UnknownTool {
                    descriptor: tool_desc,
                })
            }
        }
    }

    /// Resolve configuration and create the live session.
    pub async fn start(self) -> Result<SessionHandle, HarnessError> {
        let backend = match (self.backend, self.integration) {
            (Some(backend), _) => backend,
            (None, Some(integration)) => {
                self.integrations
                    .create(&integration.id, integration.config)
                    .await?
            }
            (None, None) => return Err(HarnessError::MissingBackend),
        };
        let tool_registry = self
            .tool_registry
            .ok_or(HarnessError::MissingToolRegistry)?;

        // A high-level toolset carries explicit policy. For callers that
        // provide a registry directly, derive an enabled/allowed toolset so
        // registered tools are also executable by the root agent.
        let root_toolset = self.root_toolset.unwrap_or_else(|| {
            let tools = tool_registry
                .descriptors()
                .into_iter()
                .map(|desc| {
                    let id = harness_protocol::ids::ToolId::new();
                    (
                        id,
                        ToolCapability {
                            descriptor: harness_protocol::tools::ToolDescriptor {
                                id,
                                name: desc.id.to_string(),
                                description: desc.description,
                                input_schema: desc.input_schema,
                            },
                            policy: ToolPolicy {
                                permission: PermissionMode::Allow,
                                enabled: true,
                            },
                            delegatable: false,
                        },
                    )
                })
                .collect();
            AgentToolset { tools }
        });
        let protocol_descriptors = root_toolset
            .enabled_descriptors()
            .into_iter()
            .cloned()
            .collect();

        let backend: Arc<dyn ExecutionBackend> = Arc::new(ToolAdvertisingBackend {
            inner: backend,
            tools: protocol_descriptors,
        });
        let workspace: Arc<dyn harness_runtime::traits::Workspace> = self
            .workspace
            .unwrap_or_else(|| Arc::new(FakeWorkspace::new()));
        let session_id = SessionId::new();
        let (event_tx, _) = broadcast::channel(256);
        let event_sink = Arc::new(BroadcastEventSink {
            tx: event_tx.clone(),
        });
        let scheduler = Arc::new(Scheduler::new(SchedulerConfig::default()));
        let runtime = Arc::new(SessionRuntime::new_with_toolset(
            session_id,
            backend,
            tool_registry,
            workspace,
            event_sink,
            root_toolset,
            scheduler,
        ));

        Ok(SessionHandle {
            client: SessionClient::new(runtime),
            session_id,
        })
    }
}

impl Default for SessionBuilder {
    fn default() -> Self {
        Self::new()
    }
}

/// Handle to a live session.
pub struct SessionHandle {
    client: SessionClient,
    session_id: SessionId,
}

impl SessionHandle {
    pub async fn send(&self, prompt: &str) -> Result<(), HarnessError> {
        self.client
            .send(SessionCommand::Prompt(UserInput {
                text: prompt.to_string(),
                attachments: vec![],
            }))
            .await?;
        Ok(())
    }

    pub fn subscribe(&self) -> broadcast::Receiver<AgentEventEnvelope> {
        self.client.subscribe()
    }

    pub fn snapshot(&self) -> SessionSnapshot {
        self.client.snapshot()
    }

    pub fn session_id(&self) -> SessionId {
        self.session_id
    }
}

//! Session client — external API for interacting with a session.
//!
//! This module provides the frontend-facing `SessionClient` handle for a
//! single session. It wraps the session runtime and translates user-facing
//! `SessionCommand`s into agent-level commands, while offering lightweight
//! read projections (snapshots) and an ordered event subscription view.

use std::sync::Arc;

use tokio::sync::broadcast;

use harness_protocol::commands::AgentStatus;
use harness_protocol::events::{AgentEventEnvelope, AgentOutcome};
use harness_protocol::ids::{AgentId, SessionId, Timestamp};
use harness_protocol::usage::{
    AgentUsageMetrics, AgentUsageSnapshot, CumulativeUsage, SessionUsageSnapshot,
};

use crate::session_runtime::{
    AgentLiveState, SessionCommand, SessionError, SessionRuntime, SessionStatus,
};

/// A lightweight read projection of the session's current state.
///
/// This is a pure function of live state — no stored copy — giving callers
/// the current snapshot of the session status, root agent status, and usage.
#[derive(Debug, Clone)]
pub struct SessionSnapshot {
    /// The session's unique identifier.
    pub session_id: SessionId,
    /// High-level session status.
    pub status: SessionStatus,
    /// The root agent's identifier (convenience field).
    pub root_agent_id: AgentId,
    /// The root agent's detailed usage/status projection.
    ///
    /// Contains information about the root agent's current run,
    /// its operation, backend, and usage tracking.
    pub root_agent_status: AgentUsageSnapshot,
    /// Aggregated usage information across the session.
    pub usage: SessionUsageSnapshot,
    /// When this snapshot was taken.
    pub timestamp: Timestamp,
}

/// Maps an agent's live runtime status onto the coarser session-level status.
///
/// `AgentStatus` returns to `Idle` after a successful run completes, so a
/// recorded [`AgentOutcome`] (from [`AgentLiveState::last_outcome`]) is what
/// distinguishes "never run" from "completed"/"cancelled" while idle.
fn session_status_from_live(live: &AgentLiveState, fallback: SessionStatus) -> SessionStatus {
    use AgentStatus::*;
    match live.status {
        PreparingContext | WaitingForBackend | Streaming | Executing | WaitingForPermission
        | WaitingForChildren | Paused => SessionStatus::Running,
        Cancelled => SessionStatus::Cancelled,
        Failed | Completed => SessionStatus::Completed,
        Idle => match live.last_outcome {
            Some(AgentOutcome::Success) | Some(AgentOutcome::Failed) => SessionStatus::Completed,
            Some(AgentOutcome::Cancelled) => SessionStatus::Cancelled,
            None => fallback,
        },
    }
}

/// Projects an [`AgentLiveState`] into the coarser [`AgentUsageMetrics`]
/// shape used by the public snapshot protocol type.
fn metrics_from_live(live: &AgentLiveState) -> AgentUsageMetrics {
    AgentUsageMetrics {
        total_runs: if live.last_outcome.is_some() { 1 } else { 0 },
        total_requests: live.total_requests,
        total_tool_calls: 0,
        total_tokens: live.usage.inclusive_usage.total_tokens,
        total_cost: live.total_cost_usd,
    }
}

/// The frontend-facing handle for a live session.
///
/// Owns an `Arc<SessionRuntime>` and provides translations between
/// user-facing `SessionCommand`s and the runtime's internal commands.
/// It also offers a stable ordered stream of events via [`Self::subscribe`].
pub struct SessionClient {
    /// The runtime that owns the session's agents and event bus.
    runtime: Arc<SessionRuntime>,
}

impl SessionClient {
    /// Create a new session client for the given runtime.
    pub fn new(runtime: Arc<SessionRuntime>) -> Self {
        Self { runtime }
    }

    /// Send a user-facing command to the session.
    ///
    /// The runtime performs the command translation and routes the resulting
    /// agent-level command through its mailbox.
    pub async fn send(&self, command: SessionCommand) -> Result<(), SessionError> {
        self.runtime.send_command(command).await
    }

    /// Take a lightweight snapshot of the session's current live state.
    ///
    /// No stored snapshot is kept; the projection is generated from the
    /// runtime's current state — including the live per-agent status/usage
    /// table that every `AgentRunner` publishes to after each transition —
    /// on every call. Immediately after `send(Prompt)` this reflects an
    /// in-flight status (e.g. `Running`); once the run completes it reflects
    /// `Completed` with populated usage.
    pub fn snapshot(&self) -> SessionSnapshot {
        let runtime_snapshot = self.runtime.state_snapshot();
        let live = self.runtime.agent_live_state(runtime_snapshot.root_agent_id);
        let status = session_status_from_live(&live, runtime_snapshot.status);
        let metrics = metrics_from_live(&live);
        let now = Timestamp::now();

        let root_agent_status = AgentUsageSnapshot {
            agent_id: runtime_snapshot.root_agent_id.to_string(),
            metrics: metrics.clone(),
            timestamp: now.to_string(),
        };

        let usage = SessionUsageSnapshot {
            session_id: runtime_snapshot.session_id.to_string(),
            cumulative: CumulativeUsage {
                total_tokens: metrics.total_tokens,
                total_cost: metrics.total_cost,
                total_requests: metrics.total_requests,
            },
            timestamp: now.to_string(),
        };

        SessionSnapshot {
            session_id: runtime_snapshot.session_id,
            status,
            root_agent_id: runtime_snapshot.root_agent_id,
            root_agent_status,
            usage,
            timestamp: now,
        }
    }

    /// Return a fresh subscriber receiver for the session's ordered events.
    ///
    /// Multiple callers can subscribe independently to the same event stream.
    pub fn subscribe(&self) -> broadcast::Receiver<AgentEventEnvelope> {
        self.runtime.event_bus.subscribe()
    }

    /// Consume this client and return its underlying runtime.
    pub fn into_runtime(self) -> Arc<SessionRuntime> {
        self.runtime
    }
}

#[cfg(test)]
mod tests {
    use std::sync::Arc;
    use std::time::Duration;

    use harness_protocol::backend::{ExecutionEvent, ExecutionResult};
    use harness_protocol::commands::UserInput;
    use harness_protocol::ids::RequestId;
    use harness_protocol::usage::{Cost, ModelUsage, UsageValue};

