// crates/harness-runtime/src/resource_manager.rs
use std::collections::HashMap;
use std::path::PathBuf;
use tokio::sync::Mutex;

use harness_protocol::ids::SessionId;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ResourceKey {
    File(PathBuf),
    GitRepository(PathBuf),
    Workspace(String),
    Terminal(String),
    Custom(String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AccessMode { Shared, Exclusive }

#[derive(Debug, thiserror::Error)]
pub enum ResourceError {
    #[error("resource {0:?} is exclusively held by another session")]
    ExclusivelyHeld(ResourceKey),
}

struct Holders {
    shared: Vec<SessionId>,
    exclusive: Option<SessionId>,
}

pub struct ResourceManager {
    state: Mutex<HashMap<ResourceKey, Holders>>,
}

impl ResourceManager {
    pub fn new() -> Self { Self { state: Mutex::new(HashMap::new()) } }

    pub async fn acquire(
        &self,
        key: ResourceKey,
        mode: AccessMode,
        holder: SessionId,
    ) -> Result<(), ResourceError> {
        let mut state = self.state.lock().await;
        let entry = state.entry(key.clone()).or_insert(Holders { shared: vec![], exclusive: None });
        match mode {
            AccessMode::Shared => {
                if entry.exclusive.is_some() {
                    return Err(ResourceError::ExclusivelyHeld(key));
                }
                entry.shared.push(holder);
                Ok(())
            }
            AccessMode::Exclusive => {
                if entry.exclusive.is_some() || !entry.shared.is_empty() {
                    return Err(ResourceError::ExclusivelyHeld(key));
                }
                entry.exclusive = Some(holder);
                Ok(())
            }
        }
    }

    pub async fn release(&self, key: ResourceKey, holder: SessionId) {
        let mut state = self.state.lock().await;
        if let Some(entry) = state.get_mut(&key) {
            entry.shared.retain(|id| *id != holder);
            if entry.exclusive == Some(holder) {
                entry.exclusive = None;
            }
        }
    }
}
```

Full `fs.edit` → `Exclusive` lock wiring is explicitly a stretch goal per the doc, not required here — this delivers the "architectural home" the spec calls for.

**Acceptance criteria:** unit tests show `Shared` can be held concurrently by multiple sessions; `Exclusive` is refused while another exclusive holder is active; released properly afterward.

**Note on the dependency:** `ResourceManager` has zero code coupling to `SessionManager` — it could be built in parallel with T1. I keep "Depends on T1" only because the doc places it after 5.1 for phase-sequencing reasons; if you want, T7 can run independently/in parallel with T1–T6 with no functional risk. Flag if you'd prefer that reordering.

